/**
 * Customer (PPPoE) portal themes.
 *
 * One shared module used by:
 *  - the customer portal shell (app/customer/layout.tsx) via PortalThemeProvider
 *  - the admin picker (app/admin/pppoe-portal/page.tsx) and its previews
 *
 * A theme is applied by setting `data-portal-theme="<id>"` on an element (the <html>
 * element for the real portal, a wrapper <div> for previews). The CSS generated by
 * `portalThemeCss()` then overrides the shadcn tokens (--primary, --card, ...), the
 * Tailwind slate scale (so existing `bg-slate-50 / dark:bg-slate-900` pages follow the
 * theme) and a few decorative variables (gradient header, glass cards, canvas glow).
 *
 * Dark mode follows the usual `.dark` class. Previews can pin a mode with
 * `data-portal-mode="light|dark"`.
 */

export type PortalThemeId = "classic" | "midnight" | "sunrise" | "forest" | "aurora"
export type PortalThemeMode = "light" | "dark"

export const DEFAULT_PORTAL_THEME: PortalThemeId = "classic"
export const PORTAL_THEME_STORAGE_KEY = "netily_customer_portal_theme"

interface ModeSpec {
  background: string
  foreground: string
  card: string
  popover?: string
  secondary: string
  muted: string
  mutedForeground: string
  accent: string
  accentForeground: string
  border: string
  primary: string
  primaryForeground: string
  ring: string
  sidebar: string
  sidebarForeground: string
  sidebarPrimary: string
  sidebarAccent: string
  sidebarBorder: string
  /** Hue/chroma of the remapped Tailwind slate scale. Omit to keep stock slate. */
  slate?: { hue: number; chroma: number }
  /** Replacement for `bg-white` surfaces in light mode. */
  surface?: string
  canvasImage?: string
  headerImage?: string
  headerForeground: string
  cardBlur?: string
  cardShadow?: string
  sidebarBlur?: string
}

export interface PortalTheme {
  id: PortalThemeId
  name: string
  description: string
  /** Short chips shown on the picker card. */
  traits: string[]
  /** Colours for the small swatch row (any CSS colour). */
  swatch: string[]
  radius: string
  /** If set, the theme only has this mode (the portal pins it and hides the toggle). */
  forcedMode?: PortalThemeMode
  light: ModeSpec
  dark: ModeSpec
}

