export function isPortalThemeId(value: unknown): value is PortalThemeId {
  return typeof value === "string" && PORTAL_THEMES.some((t) => t.id === value)
}

export function normalizePortalTheme(value: unknown): PortalThemeId {
  return isPortalThemeId(value) ? value : DEFAULT_PORTAL_THEME
}

export function getPortalTheme(id: unknown): PortalTheme {
  const normalized = normalizePortalTheme(id)
  return PORTAL_THEMES.find((t) => t.id === normalized) || PORTAL_THEMES[0]
}

// ---------------------------------------------------------------------------
// CSS generation
// ---------------------------------------------------------------------------

const SLATE_STEPS: Array<[number, number]> = [
  [50, 0.984],
  [100, 0.968],
  [200, 0.929],
  [300, 0.869],
  [400, 0.704],
  [500, 0.554],
  [600, 0.446],
  [700, 0.372],
  [800, 0.279],
  [900, 0.208],
  [950, 0.129],
]

function declarations(theme: PortalTheme, spec: ModeSpec, scheme: PortalThemeMode): string {
  const d: string[] = []
  const add = (name: string, value: string | undefined) => {
    if (value) d.push(`${name}:${value}`)
  }
  add("color-scheme", scheme)
  add("--background", spec.background)
  add("--foreground", spec.foreground)
  add("--card", spec.card)
  add("--card-foreground", spec.foreground)
  add("--popover", spec.popover || spec.card)
  add("--popover-foreground", spec.foreground)
  add("--secondary", spec.secondary)
  add("--secondary-foreground", spec.foreground)
  add("--muted", spec.muted)
  add("--muted-foreground", spec.mutedForeground)
  add("--accent", spec.accent)
  add("--accent-foreground", spec.accentForeground)
  add("--border", spec.border)
  add("--input", spec.border)
  add("--primary", spec.primary)
  add("--primary-foreground", spec.primaryForeground)
  add("--ring", spec.ring)
  add("--sidebar", spec.sidebar)
  add("--sidebar-foreground", spec.sidebarForeground)
  add("--sidebar-primary", spec.sidebarPrimary)
  add("--sidebar-primary-foreground", spec.primaryForeground)
  add("--sidebar-accent", spec.sidebarAccent)
  add("--sidebar-accent-foreground", spec.foreground)
  add("--sidebar-border", spec.sidebarBorder)
  add("--sidebar-ring", spec.ring)
  add("--radius", theme.radius)
  add("--portal-surface", spec.surface)
  add("--portal-canvas-image", spec.canvasImage || "none")
  add("--portal-header-image", spec.headerImage || "none")
  add("--portal-header-fg", spec.headerForeground)
  add("--portal-card-blur", spec.cardBlur || "none")
  add("--portal-card-shadow", spec.cardShadow || "none")
  add("--portal-sidebar-blur", spec.sidebarBlur || "none")
  if (spec.slate) {
    for (const [step, l] of SLATE_STEPS) {
      const c = step <= 100 ? spec.slate.chroma * 0.5 : spec.slate.chroma
      add(`--color-slate-${step}`, `oklch(${l} ${c.toFixed(4)} ${spec.slate.hue})`)
    }
  }
  return d.join(";")
}

let cachedCss: string | null = null

/** Static stylesheet for every theme. Built from our own data only (safe to inline). */
export function portalThemeCss(): string {
  if (cachedCss) return cachedCss
  const parts: string[] = []
  for (const theme of PORTAL_THEMES) {
    const a = `[data-portal-theme="${theme.id}"]`
    parts.push(`${a}${a}{${declarations(theme, theme.light, theme.forcedMode || "light")}}`)
    parts.push(
      `.dark${a}:not([data-portal-mode="light"]),.dark ${a}:not([data-portal-mode="light"]),${a}[data-portal-mode="dark"]{${declarations(theme, theme.dark, "dark")}}`,
    )
  }
  // Shared decorative hooks. Classes are applied by the portal shell and the previews.
  parts.push(
    `[data-portal-theme] .portal-canvas{background-image:var(--portal-canvas-image,none)}`,
    `[data-portal-theme] .portal-sidebar{-webkit-backdrop-filter:var(--portal-sidebar-blur,none);backdrop-filter:var(--portal-sidebar-blur,none)}`,
    `[data-portal-theme] .portal-header{background-image:var(--portal-header-image,none);color:var(--portal-header-fg,inherit)}`,
    `[data-portal-theme] [data-slot="card"]{-webkit-backdrop-filter:var(--portal-card-blur,none);backdrop-filter:var(--portal-card-blur,none);box-shadow:var(--portal-card-shadow,none)}`,
    `[data-portal-theme]:not(.dark):not(.dark *) .bg-white{background-color:var(--portal-surface,#fff)}`,
  )
  cachedCss = parts.join("\n")
  return cachedCss
}
